L = 1650
M = 1850
F = 4500
for p in products:
    if p not in a or p not in b or p not in s or (p not in v):
        raise ValueError(f'Missing data for product: {p}')
m = gp.Model('RedBeanClothingFactory')
x = m.addVars(products, lb=0, vtype=GRB.CONTINUOUS, name='')
profit_expr = gp.quicksum(((s[p] - v[p]) * x[p] for p in products)) - F
m.setObjective(profit_expr, GRB.MAXIMIZE)
m.addConstr(gp.quicksum((a[p] * x[p] for p in products)) <= L, name='labor')
m.addConstr(gp.quicksum((b[p] * x[p] for p in products)) <= M, name='material')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')